using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Rendering;using MapSharedProps;using MapSharedProps.EditorTools;
public static class BareSoilChecks {
 public static void Run(){var args=Environment.GetCommandLineArgs();string output=args[Array.IndexOf(args,"-nature-output")+1];int code=0;try{UnityEditor.SceneManagement.EditorSceneManager.NewScene(UnityEditor.SceneManagement.NewSceneSetup.EmptyScene,UnityEditor.SceneManagement.NewSceneMode.Single);var rd=ScriptableObject.CreateInstance<UnityEngine.Rendering.Universal.UniversalRendererData>();var rp=UnityEngine.Rendering.Universal.UniversalRenderPipelineAsset.Create(rd);rp.shadowDistance=50;var so=new SerializedObject(rp);so.FindProperty("m_MainLightShadowsSupported").boolValue=true;so.ApplyModifiedPropertiesWithoutUndo();GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=Color.white;var floor=GameObject.CreatePrimitive(PrimitiveType.Plane);floor.transform.localScale=Vector3.one*6;var sun=new GameObject("Bare soil sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1;sun.shadows=LightShadows.Hard;sun.transform.rotation=Quaternion.LookRotation(new Vector3(3,-8,5));var camera=new GameObject("Bare soil camera").AddComponent<Camera>();camera.gameObject.AddComponent<UnityEngine.Rendering.Universal.UniversalAdditionalCameraData>();camera.aspect=1.6f;camera.farClipPlane=200;Validate(output,camera,floor,sun);}catch(Exception e){code=1;Debug.LogException(e);}EditorApplication.Exit(code);}
 [Serializable]class Row{public string name;public bool passed;}[Serializable]class Report{public string status;public Row[] checks;}
 static List<Row> rows=new List<Row>();static void Check(string name,bool ok){rows.Add(new Row{name=name,passed=ok});if(!ok)throw new Exception(name);}
 public static void Validate(string output,Camera camera,GameObject floor,Light sun){try{
  sun.shadowBias=.01f;sun.shadowNormalBias=.02f;var lightData=sun.GetComponent<UnityEngine.Rendering.Universal.UniversalAdditionalLightData>();if(!lightData)lightData=sun.gameObject.AddComponent<UnityEngine.Rendering.Universal.UniversalAdditionalLightData>();lightData.usePipelineSettings=false;
  var built=MapSharedPropsBuilder.Build(Path.Combine(output,"bare-export"));Check("50 shared models, existing eight object placements",built.prefabs.Count==50&&built.placed==8);Check("one derived paint texture shared by trees",built.rootPaint&&built.rootPaint.mipmapCount==1&&built.prefabs["pine"].GetComponent<Renderer>().sharedMaterial.GetTexture("_RootPaint")==built.rootPaint);var imp=(TextureImporter)AssetImporter.GetAtPath(AssetDatabase.GetAssetPath(built.rootPaint));Check("paint data stays linear, bilinear, uncompressed and unscaled",!imp.sRGBTexture&&imp.filterMode==FilterMode.Bilinear&&imp.textureCompression==TextureImporterCompression.Uncompressed&&imp.npotScale==TextureImporterNPOTScale.None);
  var floorMat=built.ground.material;floorMat.SetVector("_EditorZero",Vector4.zero);floorMat.SetFloat("_DirtWeight",1);floor.GetComponent<Renderer>().sharedMaterial=floorMat;UnityEngine.Object.DestroyImmediate(built.root);
  var human=GameObject.CreatePrimitive(PrimitiveType.Capsule);human.name="1.8m reference";human.transform.localScale=new Vector3(.35f,.9f,.35f);human.transform.position=new Vector3(1.8f,.9f,0);var personMat=new Material(Shader.Find("Universal Render Pipeline/Lit"));personMat.SetColor("_BaseColor",new Color(.18f,.21f,.23f));human.GetComponent<Renderer>().sharedMaterial=personMat;
  foreach(var id in new[]{"pine","sugi","hinoki","bush","hazel","grass","worldtree"}){var obj=(GameObject)PrefabUtility.InstantiatePrefab(built.prefabs[id]);obj.transform.position=new Vector3(0,id=="bush"?-.05f:0,0);var renderer=obj.GetComponent<Renderer>();SharedRootGrounding.SetSurface(renderer,new Vector4(1,0,0,id=="bush"?.05f:0));bool big=id=="worldtree";human.transform.position=new Vector3(big?7:1.8f,.9f,0);camera.orthographic=true;camera.orthographicSize=big?4.4f:1.9f;camera.transform.position=new Vector3(big?11:3.2f,big?4.2f:1.6f,big?15:5.2f);camera.transform.LookAt(new Vector3(0,big?.7f:.22f,0));Shader.SetGlobalVector("_TDPineOrigin",Vector4.zero);Shader.SetGlobalVector("_TDPineWind",Vector4.zero);
   foreach(bool on in new[]{true,false}){sun.enabled=on;Capture(camera,output,"unity-soil-"+id+"-sun-"+on+".png");}Check(id+" opaque/cutout shared shader ready",renderer.sharedMaterial.shader.isSupported&&renderer.sharedMaterials.Length==1);UnityEngine.Object.DestroyImmediate(obj);
  }UnityEngine.Object.DestroyImmediate(human);sun.enabled=true;Write(output,"Passed");
 }catch{Write(output,"Failed");throw;}}
 static void Write(string output,string status){File.WriteAllText(Path.Combine(output,"bare-soil-unity.json"),JsonUtility.ToJson(new Report{status=status,checks=rows.ToArray()},true));}
 static void Capture(Camera camera,string output,string name){var rt=new RenderTexture(1280,800,24);rt.Create();camera.targetTexture=rt;RenderPipeline.SubmitRenderRequest(camera,new RenderPipeline.StandardRequest{destination=rt});var old=RenderTexture.active;RenderTexture.active=rt;var im=new Texture2D(1280,800,TextureFormat.RGBA32,false);im.ReadPixels(new Rect(0,0,1280,800),0,0);im.Apply();File.WriteAllBytes(Path.Combine(output,name),im.EncodeToPNG());RenderTexture.active=old;camera.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(im);}
}
